import{_ as a,o as d,c as i,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"शिक्षा-गारंटी कानून","description":"","frontmatter":{},"headers":[],"relativePath":"hi/0043-教育保障法.md","filePath":"hi/0043-教育保障法.md"}'),l={name:"hi/0043-教育保障法.md"};function e(o,t,h,n,s,u){return d(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="शिक्षा-गारंटी-कानून" tabindex="-1">शिक्षा-गारंटी कानून <a class="header-anchor" href="#शिक्षा-गारंटी-कानून" aria-label="Permalink to &quot;शिक्षा-गारंटी कानून&quot;">​</a></h1><table tabindex="0"><thead><tr><th>मद</th><th>सामग्री</th></tr></thead><tbody><tr><td>दस्तावेज़ संख्या</td><td>43</td></tr><tr><td>मॉड्यूल</td><td>कानूनी प्रणाली और शासन-ढाँचा</td></tr><tr><td>कीवर्ड</td><td>शिक्षा-अधिकार, सहजीवी शिक्षा, साधना-परंपरा, आजीवन अधिगम, शैक्षिक समानता</td></tr></tbody></table><h2 id="i-विधायी-उद्देश्य-और-मूल-सिद्धांत" tabindex="-1">I. विधायी उद्देश्य और मूल सिद्धांत <a class="header-anchor" href="#i-विधायी-उद्देश्य-और-मूल-सिद्धांत" aria-label="Permalink to &quot;I. विधायी उद्देश्य और मूल सिद्धांत&quot;">​</a></h2><p><em>शिक्षा-गारंटी कानून</em> लंगर सहजीवी सभ्यता के पाँच सहायक कानूनों में से एक है। इसका उद्देश्य हेंग-ब्रह्मांड के भीतर सभी जीवनों के शिक्षा-अधिकार की गारंटी, &quot;सहजीवी विकास&quot; को मूल अवधारणा मानने वाली शिक्षा-प्रणाली स्थापित करना और दस हजार जातियों के साझा उन्नयन के लिए ज्ञान और प्रतिभा-सहायता प्रदान करना है।</p><p>यह कानून निम्न मूल सिद्धांत स्थापित करता है:</p><table tabindex="0"><thead><tr><th>सिद्धांत</th><th>अर्थ</th></tr></thead><tbody><tr><td>शैक्षिक समानता</td><td>सभी जीवन, चाहे जाति, साधना या जन्म कुछ भी हो, समान शिक्षा-अवसर प्राप्त करते हैं</td></tr><tr><td>योग्यतानुसार शिक्षा</td><td>प्रत्येक जीवन की प्रतिभा-भिन्नता और विकास-पथ चयन का सम्मान, व्यक्तिगत शिक्षा-योजनाएँ प्रदान करना</td></tr><tr><td>ज्ञान-कर्म एकता</td><td>सैद्धांतिक ज्ञान और व्यावहारिक साधना का संयोजन; वास्तविकता से कटी खोखली शिक्षा का विरोध</td></tr><tr><td>खुलापन-साझापन</td><td>शैक्षिक संसाधन पूरे समाज के लिए खुले; तीन सौ मूल साधना-प्रणालियों के आधार मंत्र निःशुल्क सिखाए जाते हैं</td></tr><tr><td>आजीवन अधिगम</td><td>शिक्षा जीवन की पूरी प्रक्रिया में व्याप्त; सभी चरणों में निरंतर अधिगम और क्षमता-वृद्धि का समर्थन</td></tr><tr><td>सांस्कृतिक बहुलता</td><td>सभी जातियों की सांस्कृतिक परंपराओं का सम्मान, बहुसांस्कृतिक आदान-प्रदान और परस्पर-सीख को प्रोत्साहन</td></tr></tbody></table><h2 id="ii-शिक्षा-अधिकार-की-कानूनी-गारंटी" tabindex="-1">II. शिक्षा-अधिकार की कानूनी गारंटी <a class="header-anchor" href="#ii-शिक्षा-अधिकार-की-कानूनी-गारंटी" aria-label="Permalink to &quot;II. शिक्षा-अधिकार की कानूनी गारंटी&quot;">​</a></h2><p>यह कानून स्पष्ट करता है कि शिक्षा-अधिकार सहजीवी संविधान द्वारा प्रत्येक जीवन को प्रदत्त मूल अधिकार है, और राज्य तथा सभ्यता पर इस अधिकार की प्राप्ति सुनिश्चित करने का दायित्व है:</p><ol><li><strong>निःशुल्क मूल शिक्षा</strong>: सभी जीवनों को निःशुल्क मूल शिक्षा पाने का अधिकार, जिसमें सामान्य ज्ञान, आधार साधना-मंत्र, सहजीवी सभ्यता-विचार आदि शामिल; शैक्षिक अवधि छह से बारह वर्ष, जाति के विकास-चक्र के अनुसार समायोजित।</li><li><strong>निःशुल्क साधना-प्रवेश</strong>: तीन सौ मूल साधना-प्रणालियों के आधार मंत्र सभी जीवनों के लिए निःशुल्क खुले; कोई संगठन या व्यक्ति आधार साधना-मंत्रों को निजी संपत्ति बनाकर शुल्क पर नहीं सिखा सकता।</li><li><strong>उन्नति-अवसर समानता</strong>: सभी स्तरों के शैक्षिक संस्थान प्रवेश में जाति, साधना, जन्म-आधारित भेदभावपूर्ण शर्तें नहीं लगा सकते; प्रवेश-मानदंड खुले और पारदर्शी।</li><li><strong>विशेष शिक्षा गारंटी</strong>: विकलांग जीवनों, अन्य-जाति जीवनों, दूरस्थ पटलों के जीवनों आदि समूहों के लिए अनुकूलित विशेष शिक्षा-संसाधन और दूरस्थ शिक्षा-सहायता प्रदान करना।</li><li><strong>शिक्षा-सहायता व्यवस्था</strong>: आर्थिक रूप से कठिनाई में सीखने वालों को छात्रवृत्ति, उत्कृष्टता-वृत्ति और ब्याज-मुक्त ऋण प्रदान करना, यह सुनिश्चित करना कि आर्थिक कारणों से शिक्षा-अवसर न छूटे।</li></ol><h2 id="iii-शिक्षा-प्रणाली-की-संरचना" tabindex="-1">III. शिक्षा-प्रणाली की संरचना <a class="header-anchor" href="#iii-शिक्षा-प्रणाली-की-संरचना" aria-label="Permalink to &quot;III. शिक्षा-प्रणाली की संरचना&quot;">​</a></h2><p>लंगर सहजीवी सभ्यता की शिक्षा-प्रणाली चार स्तरों में विभाजित है, स्तरों के बीच जैविक समन्वय:</p><table tabindex="0"><thead><tr><th>स्तर</th><th>नाम</th><th>लक्ष्य</th><th>शैक्षिक अवधि</th></tr></thead><tbody><tr><td>प्रथम स्तर</td><td>आरंभिक शिक्षा</td><td>मूल संज्ञान-क्षमता और सहजीवी चेतना का विकास; आधार साधना-मंत्र सिखाना</td><td>3-6 वर्ष</td></tr><tr><td>द्वितीय स्तर</td><td>मूल शिक्षा</td><td>सामान्य ज्ञान और साधना-सिद्धांत का व्यवस्थित अधिगम; व्यक्ति की प्रतिभा-दिशा पहचानना</td><td>6-9 वर्ष</td></tr><tr><td>तृतीय स्तर</td><td>व्यावसायिक शिक्षा</td><td>चुनी गई साधना-प्रणाली या व्यावसायिक क्षेत्र में गहन अधिगम और अभ्यास</td><td>3-10 वर्ष</td></tr><tr><td>चतुर्थ स्तर</td><td>उच्च अनुसंधान</td><td>उच्च साधकों और शोधकर्ताओं के लिए सीमांत अन्वेषण और नवाचारी अनुसंधान</td><td>असीमित</td></tr></tbody></table><p>इसके अतिरिक्त, &quot;मार्गदर्शक-जाल व्यवस्था&quot; स्थापित है: निश्चित साधना-स्तर पाने वाले साधकों पर क्षमता के भीतर प्रारंभिक साधकों का मार्गदर्शन करने का दायित्व है; मार्गदर्शन-योगदान संयुक्त-उत्पादन ठेका तंत्र की योगदान-मात्रा में गिना जाता है और संगत संसाधन-वितरण प्राप्त करता है।</p><h2 id="iv-शैक्षिक-संस्थान-और-शिक्षक" tabindex="-1">IV. शैक्षिक संस्थान और शिक्षक <a class="header-anchor" href="#iv-शैक्षिक-संस्थान-और-शिक्षक" aria-label="Permalink to &quot;IV. शैक्षिक संस्थान और शिक्षक&quot;">​</a></h2><ul><li><strong>सार्वजनिक शैक्षिक संस्थान</strong>: राज्य या सभ्यता-समुदाय द्वारा स्थापित, निःशुल्क मूल शिक्षा और सार्वजनिक शैक्षिक सेवाएँ वहन, वित्त-पोषण सार्वजनिक संचय से सुनिश्चित।</li><li><strong>निजी शैक्षिक संस्थान</strong>: सामाजिक शक्तियों द्वारा कानूनानुसार स्थापित; उचित शुल्क ले सकते हैं, किंतु शिक्षा-प्रशासन विभाग की निगरानी स्वीकारनी होगी; झूठा प्रचार और शिकारी शुल्क-वसूली नहीं कर सकते।</li><li><strong>साधना-संप्रदाय</strong>: पारंपरिक साधना-संगठन पंजीकरण के बाद व्यावसायिक शैक्षिक संस्थान के रूप में कार्य कर सकते हैं; शिक्षा-कानून का पालन करना होगा, साधना-संसाधनों को बंद-एकाधिकार नहीं कर सकते।</li><li><strong>शिक्षकों के अधिकार और दायित्व</strong>: शिक्षकों को शैक्षणिक स्वतंत्रता, उचित पारिश्रमिक, व्यावसायिक प्रशिक्षण जैसे अधिकार मिलते हैं; साथ ही पढ़ाने-संस्कारित करने, आदर्श-रूप होने, छात्र-गोपनीयता की रक्षा जैसे दायित्व भी।</li></ul><h2 id="v-शिक्षा-सामग्री-और-पाठ्यक्रम-मानक" tabindex="-1">V. शिक्षा-सामग्री और पाठ्यक्रम मानक <a class="header-anchor" href="#v-शिक्षा-सामग्री-और-पाठ्यक्रम-मानक" aria-label="Permalink to &quot;V. शिक्षा-सामग्री और पाठ्यक्रम मानक&quot;">​</a></h2><p>शिक्षा-सामग्री को निम्न आवश्यकताएँ पूरी करनी होंगी:</p><ol><li>सहजीवी सभ्यता की मूल अवधारणाएँ और शिकार-विरोधी शिक्षा शामिल, सीखने वालों की सहजीवी चेतना विकसित करना।</li><li>तीन सौ मूल साधना-प्रणालियों के मूल सिद्धांत और प्रवेश-मंत्र शामिल।</li><li>ब्रह्मांडीय नियम, पटल-ज्ञान, जीवन-विज्ञान जैसे सामान्य वैज्ञानिक ज्ञान शामिल।</li><li>दस हजार जातियों का इतिहास और संस्कृति शामिल, परस्पर समझ और सम्मान बढ़ाना।</li><li>व्यावहारिक साधना और सामाजिक सेवा-घटक शामिल, ज्ञान-कर्म एकता की क्षमता विकसित करना।</li><li>शिकारी साधना-विचारों और भेदभावपूर्ण विचारों का प्रसार निषिद्ध।</li></ol><h2 id="vi-कानूनी-दायित्व" tabindex="-1">VI. कानूनी दायित्व <a class="header-anchor" href="#vi-कानूनी-दायित्व" aria-label="Permalink to &quot;VI. कानूनी दायित्व&quot;">​</a></h2><p>इस कानून के प्रावधानों का उल्लंघन करने वाले कृत्य परिस्थितियों की गंभीरता के अनुसार निम्न दायित्व वहन करते हैं:</p><ul><li>शिक्षा-आयु वाले जीवनों को अनिवार्य शिक्षा लेने से मना करने या बाधित करने पर सुधार-आदेश और दंड।</li><li>नियम-विरुद्ध शुल्क लेने या झूठा प्रचार करने वाले शैक्षिक संस्थानों पर शुल्क-वापसी और जुर्माना; गंभीर परिस्थितियों में विद्यालय-संचालन लाइसेंस निरस्त।</li><li>छात्रों को शारीरिक दंड देने या भेदभाव करने वाले शिक्षकों पर दंड; गंभीर परिस्थितियों में शिक्षक-योग्यता निरस्त और कानूनी दायित्व।</li><li>सार्वजनिक साधना-संसाधनों को निजी बनाने या शुल्क-एकाधिकार करने पर अवैध आय जब्त और जुर्माना।</li></ul><h2 id="निष्कर्ष" tabindex="-1">निष्कर्ष <a class="header-anchor" href="#निष्कर्ष" aria-label="Permalink to &quot;निष्कर्ष&quot;">​</a></h2><p><em>शिक्षा-गारंटी कानून</em> लंगर सहजीवी सभ्यता की &quot;हर किसी के लिए मार्ग&quot; दर्शन की शैक्षिक प्रथा है। शिक्षा-अधिकार की गारंटी, बहु-स्तरीय शिक्षा-प्रणाली के निर्माण, साधना-संसाधनों को खोलने के माध्यम से यह सुनिश्चित करता है कि प्रत्येक जीवन को अपने अनुकूल विकास-पथ मिले, दस हजार जातियों के साझा उन्नयन को निरंतर ज्ञान और प्रतिभा की आपूर्ति करता है।</p><h2 id="संबंधित-दस्तावेज़" tabindex="-1">संबंधित दस्तावेज़ <a class="header-anchor" href="#संबंधित-दस्तावेज़" aria-label="Permalink to &quot;संबंधित दस्तावेज़&quot;">​</a></h2><ul><li>40-共生宪法总纲 (सहजीवी संविधान: सामान्य सिद्धांत)</li><li>37-共生教育体系 (सहजीवी शिक्षा-प्रणाली)</li><li>10-三百套本源修炼体系总览 (तीन सौ मूल साधना-प्रणालियों का सिंहावलोकन)</li><li>08-人人有路保障体系 (हर किसी के लिए मार्ग गारंटी-प्रणाली)</li></ul>',25)])])}const _=a(l,[["render",e]]);export{c as __pageData,_ as default};
